/* Avrana Media service worker (MK-3, AVR-717). Generated by pwa.py: BUILD, OFFLINE and ALLOW are filled in from code.

   What it does, and all it does:
     * Page navigations go to the network untouched (the original request, so a redirect to sign-in stays a
       redirect the browser follows). Only when the network itself fails (a thrown TypeError) does it answer with
       the cached offline page. A 302, 401, 403, 404 or 5xx is a response, and is returned as it is.
     * An exact list of static, identical-for-everyone files (the page script, the offline page, the brand font,
       lockup, favicon and icons) is stored when this worker installs and served from that store.
     * Every other request is left alone: no respondWith, so the browser handles it as if no worker existed.
       Member pages, artwork, search, JSON and the manifest are never read, stored or cached here.
   It reads no credentials or request headers, stores no Request, and keeps nothing in any other storage. */
'use strict';

const BUILD = '__BUILD__';
const CACHE = 'avrana-shell-' + BUILD;
const PREFIX = 'avrana-';
const OFFLINE = '__OFFLINE__';
/* exact path -> the one content type it may be stored with */
const ALLOW = __ALLOW__;
const MAX_BYTES = 524288;

function allowed(path) {
  return Object.prototype.hasOwnProperty.call(ALLOW, path);
}

/* The cache-poisoning guard. Only a same-origin, directly answered 200 of the expected type is ever stored; a login
   page served in place of a font, a redirect that was followed, an opaque or error response is refused. */
async function storable(response, path) {
  if (!response || response.status !== 200 || response.type !== 'basic' || response.redirected) return false;
  const type = (response.headers.get('content-type') || '').split(';')[0].trim().toLowerCase();
  if (!allowed(path) || type !== ALLOW[path]) return false;
  if ((response.headers.get('vary') || '').indexOf('*') !== -1) return false;
  const blob = await response.clone().blob();
  return blob.size > 0 && blob.size <= MAX_BYTES;
}

self.addEventListener('install', function (event) {
  event.waitUntil((async function () {
    const staged = [];
    for (const path of Object.keys(ALLOW)) {
      const response = await fetch(new Request(path, { cache: 'reload', redirect: 'error', credentials: 'same-origin' }));
      if (!(await storable(response, path))) throw new Error('refused');
      staged.push([path, response]);
    }
    /* all or nothing: any refusal above ends the install and the previous worker stays in charge */
    const cache = await caches.open(CACHE);
    try {
      for (const entry of staged) await cache.put(entry[0], entry[1]);
    } catch (error) {
      await caches.delete(CACHE);
      throw error;
    }
  })());
});

self.addEventListener('activate', function (event) {
  event.waitUntil(caches.keys().then(function (keys) {
    return Promise.all(keys.filter(function (key) { return key.indexOf(PREFIX) === 0 && key !== CACHE; })
      .map(function (key) { return caches.delete(key); }));
  }));
});

/* The page asks a waiting worker to take over, with exactly this message and nothing else. */
self.addEventListener('message', function (event) {
  const data = event.data;
  if (data && typeof data === 'object' && data.type === 'SKIP_WAITING' && Object.keys(data).length === 1) {
    self.skipWaiting();
  }
});

async function offlinePage() {
  const cache = await caches.open(CACHE);
  return (await cache.match(OFFLINE, { ignoreVary: true })) || Response.error();
}

async function staticFile(request, path) {
  const cache = await caches.open(CACHE);
  const hit = await cache.match(path, { ignoreVary: true });
  if (hit) return hit;
  const response = await fetch(request);
  if (await storable(response, path)) await cache.put(path, response.clone());
  return response;
}

self.addEventListener('fetch', function (event) {
  const request = event.request;
  if (request.mode === 'navigate') {
    event.respondWith(fetch(request).catch(function (error) {
      if (error instanceof TypeError) return offlinePage();
      throw error;
    }));
    return;
  }
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin || url.search || url.pathname === OFFLINE || !allowed(url.pathname)) return;
  event.respondWith(staticFile(request, url.pathname));
});
